      (1, 6225, 3, '0065D779', '3694741087', null, '2023-01-13', '2023-01-18 08:36:53', '2023-02-17', 44, 44, 'MEDICAMENTOS -  INGRESO 5131', 1012, 1350, 1, 'V', 'HJU', null, null, 'HJU', '2023-05-02 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 9, 2023, null, 1, 0, 0, 0, null, null, '5131', 'HJU', null, null, 40, 3, null, null),
      (1, 6226, 3, '7C404651', '110904786', null, '2023-01-13', '2023-01-18 08:43:32', '2023-02-10', 44, 44, 'MEDICAMENTOS - INGRESO 5132', 1012, 129.6, 1, 'V', 'HJU', null, null, 'HJU', '2023-03-02 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 9, 2023, null, 1, 0, 0, 0, null, null, '5132', 'HJU', null, null, 40, 3, null, null),
      (1, 6227, 3, '3D5C4F52', '2816427102', null, '2023-01-13', '2023-01-18 08:56:02', '2023-02-12', 361, 361, 'MEDICAMENTOS - INGRESO 5133', 1002, 825.73, 1, 'V', 'HJU', null, null, 'HJU', '2023-03-02 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2023, null, 1, 0, 0, 0, null, null, '5133', 'HJU', null, null, 40, 4, null, null),
      (1, 6228, 3, '61D2E552', '3575006725', null, '2023-01-13', '2023-01-18 08:57:45', '2023-02-12', 223, 223, 'MEDICAMENTOS - INGRESO 5134', 1002, 850.44, 1, 'V', 'HJU', null, null, 'HJU', '2023-03-02 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2023, null, 1, 0, 0, 0, null, null, '5134', 'HJU', null, null, 40, 4, null, null),
      (1, 6229, 3, 'B910A887', '791626573', null, '2023-01-13', '2023-01-18 08:59:33', '2023-01-13', 223, 223, 'MEDICAMENTOS - INGRESO 5135', 1002, 240, 1, 'V', 'HJU', null, null, 'HJU', '2023-05-02 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2023, null, 1, 0, 0, 0, null, null, '5135', 'HJU', null, null, 40, 3, null, null),
      (1, 6230, 3, '892959CD', '2999273005', null, '2023-01-16', '2023-01-18 09:10:20', '2023-01-16', 625, 625, 'SERVICIOS', 1039, 6980, 7.7, 'V', 'HJU', null, null, 'HJU', '2023-01-18 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 4, 2023, null, 1, 0, 0, 0, null, null, null, null, 'C', true, 10, 10, null, null),
      (1, 6231, 3, 'ACC099E8', '4083500217', null, '2023-01-17', '2023-01-18 09:11:56', '2023-01-17', 2362, 2362, 'SERVICIOS PRESTADOS', 1039, 6000, 7.7, 'V', 'HJU', null, null, 'HJU', '2023-01-18 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 1, 2023, null, 1, 0, 0, 0, null, null, null, null, 'C', true, 10, 10, null, null),
      (1, 6232, 3, 'CF2C388B', '868697208', null, '2021-11-23', '2023-01-18 09:51:50', '2021-11-23', 39, 39, 'compra generada automaticamente para Ingreso 4079', 1002, 5700, 1, 'V', 'HJU', null, null, null, null, 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2021, null, 11, 0, 0, 0, null, null, '4079', null, null, null, 40, 4, null, null),
      (1, 6233, 3, 'B7D83BF9', '3745074729', null, '2023-01-13', '2023-01-18 10:24:43', '2023-01-13', 2337, 2337, 'compra generada automaticamente para Ingreso 5138', 1003, 1400, 1, 'V', 'BJL', null, null, 'HJU', '2023-05-02 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2023, null, 1, 0, 0, 0, null, null, '5138', 'HJU', null, null, 40, 4, null, null),
      (1, 6234, 3, '1A006A04', '2987541824', null, '2023-01-03', '2023-01-18 10:48:46', '2023-01-03', 2328, 2328, 'compra generada automaticamente para Ingreso 5139', 1003, 3184, 1, 'V', 'BJL', null, null, 'HJU', '2023-05-02 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2023, null, 1, 0, 0, 0, null, null, '5139', 'HJU', null, null, 40, 4, null, null),
      (1, 6235, 4, '9A1420E8', '1781350985', null, '2023-01-07', '2023-01-18 15:03:00', '2023-01-07', 214, 214, 'HONORARIOS SEGUN ORDEN NO. 10212', 1007, 14425.89, 7.7, 'V', 'BJL', null, null, 'HJU', '2023-05-02 00:00:00', 'V', null, null, null, 12, 5, 674.11, true, null, 0, null, null, null, null, null, 0, true, null, null, null, 1, 2023, null, 1, 0, 0, 0, null, null, null, 'HJU', 'C', true, 10, 2, null, null)),
  m as (
    select m0.*, coalesce(round(m0.gal_super * g.idp_super + m0.gal_regular * g.idp_regular + m0.gal_diesel * g.idp_diesel, 2), 0) as idp,
           m0.estado = 'V' and exists (select 1 from public.compras c where c.localidad_id = l.id and c.origen_anterior is null and c.estado = 'ACTIVA'
             and c.tipo_documento = case when t.es_recibo then 'RECIBO' else 'FACTURA' end and upper(coalesce(c.proveedor_codigo, c.proveedor_nombre)) = m0.proveedor::text
             and upper(coalesce(c.serie, '')) = coalesce(m0.serie, '') and upper(c.documento) = m0.documento) as doc_rep
    from m0 join public.localidades l on l.organizacion_id = v_org and l.correlativo = m0.loc
    left join public.tipos_documento_compra t on t.codigo = m0.tipo_doc
    left join lateral (select coalesce(p.idp_super, 0) as idp_super, coalesce(p.idp_regular, 0) as idp_regular, coalesce(p.idp_diesel, 0) as idp_diesel
                       from public.parametros_generales p where p.localidad_id = l.id order by p.id limit 1) g on true),
  x as (
    insert into public.compras (organizacion_id, localidad_id, numero, tipo_documento, tipo_documento_id, serie, documento, fecha_documento, fecha_ingreso, fecha_vencimiento,
           tipo_tercero, proveedor_id, proveedor_codigo, proveedor_nombre, nit, beneficiario, transaccion_id, descripcion, moneda_id, tipo_cambio, valor_total,
           forma_pago, estado, anulado_por, anulado_en, motivo_anulacion, usuario, mes_presentacion, anio_presentacion, pago_inmediato, dias_credito, factura_original,
           regimen_isr_id, clasificacion_id, galones_super, galones_regular, galones_diesel, exento, retencion, retencion_valor, retencion_formulario, retencion_fecha, orden_compra,
           origen_anterior, compra_anterior, modulo_factura, numero_cheque, usuario_modifica_anterior, fecha_modifica_anterior, tipo_compra_anterior, poliza_anio, poliza_mes, poliza_numero,
           pct_iva, pct_retencion, propina, fecha_transferencia, clasificacion_pago, usuario_autoriza, tipo_periodo_compra, transaccion_retencion, valor_cambio_anterior,
           documento_anterior, proveedor_anterior, transaccion_anterior, regimen_isr_anterior, fecha_ingreso_anterior, usuario_anula_anterior, fecha_anula_anterior,
           cuenta_bancaria_anterior, transferencia_anterior, banco_anterior, contrasena_anterior, exento_anterior, anio_presentacion_anterior, retencion_valor_anterior, fecha_documento_anterior, fecha_vencimiento_anterior)
    select v_org, l.id, m.compra, case when t.es_recibo then 'RECIBO' else 'FACTURA' end, t.id, m.serie, case when m.doc_rep then m.documento || ' (MIGRADA)' else m.documento end, coalesce(m.fecha_documento, m.fecha_ingreso::date), coalesce(m.fecha_ingreso::date, m.fecha_documento), m.fecha_venc,
           case when m.tipo_compra = 'M' then 'PROVEEDOR PRODUCTOS' else 'PROVEEDOR SERVICIOS' end, p.id, m.proveedor::text,
           upper(coalesce(p.nombre_comercial, 'PROVEEDOR ' || m.proveedor)), p.nit, coalesce(p.beneficiario, upper(p.nombre_comercial)),
           (select x.id from public.transacciones_contables x where x.localidad_id = l.id and x.numero = m.transaccion), m.descripcion, v_gtq, 1, m.valor_total,
           'CHEQUE', case when m.estado = 'A' then 'ANULADA' else 'ACTIVA' end, case when m.estado = 'A' then coalesce(m.usr_anula, 'SISTEMA ANTERIOR') end,
           case when m.estado = 'A' then coalesce(m.f_anula, m.fecha_ingreso) at time zone 'America/Guatemala' end, case when m.estado = 'A' then 'ANULADA EN EL SISTEMA ANTERIOR' end,
           m.usuario, m.mes_pres, m.anio_pres, coalesce(m.pago_inmediato, false),
           case when coalesce(m.pago_inmediato, false) or m.fecha_venc is null then 0 else greatest(m.fecha_venc - coalesce(m.fecha_documento, m.fecha_ingreso::date), 0) end, coalesce(m.original, true),
           (select g.id from public.regimenes_isr g where g.codigo = m.regimen), (select k.id from public.clasificaciones_compra k where k.codigo = m.clasif),
           m.gal_super, m.gal_regular, m.gal_diesel, case when m.idp > 0 then greatest(m.exento - m.idp, 0) else m.exento end, coalesce(m.retencion, false), case when m.retencion then coalesce(m.valor_retencion, 0) else 0 end,
           case when m.retencion then m.formulario end, case when m.retencion then m.fecha_ret end, m.orden_compra,
           'VARIAS', m.compra, m.modulo, m.numero_cheque, m.usr_mod, m.f_mod::date, m.tipo_compra, m.poliza_anio, m.poliza_mes, m.poliza_numero,
           m.pct_iva, m.pct_retencion, m.propina, m.fecha_transf, m.clasif_pago, m.usr_autoriza, m.tipo_periodo, m.trans_ret, m.valor_cambio,
           case when m.doc_rep then coalesce(m.documento_ant, m.documento) else m.documento_ant end, m.proveedor_ant, m.transaccion, m.regimen, m.fecha_ingreso, m.usr_anula, m.f_anula,
           m.cuenta_bancaria, m.transferencia, m.banco, m.contrasena, case when m.idp > 0 then coalesce(m.exento_ant, m.exento) else m.exento_ant end, m.anio_pres_ant, m.valor_retencion, m.fecha_doc_ant, m.fecha_venc_ant
    from m
    join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
    left join public.proveedores p on p.localidad_id = l.id and p.codigo = m.proveedor
    left join public.tipos_documento_compra t on t.codigo = m.tipo_doc
    on conflict (localidad_id, origen_anterior, compra_anterior) where origen_anterior is not null do update set
      tipo_documento = excluded.tipo_documento, tipo_documento_id = excluded.tipo_documento_id, serie = excluded.serie, documento = excluded.documento,
      fecha_documento = excluded.fecha_documento, fecha_ingreso = excluded.fecha_ingreso, fecha_vencimiento = excluded.fecha_vencimiento, tipo_tercero = excluded.tipo_tercero,
      proveedor_id = excluded.proveedor_id, proveedor_codigo = excluded.proveedor_codigo, proveedor_nombre = excluded.proveedor_nombre, nit = excluded.nit, beneficiario = excluded.beneficiario,
      transaccion_id = excluded.transaccion_id, descripcion = excluded.descripcion, valor_total = excluded.valor_total, estado = excluded.estado, anulado_por = excluded.anulado_por,
      anulado_en = excluded.anulado_en, motivo_anulacion = excluded.motivo_anulacion, usuario = excluded.usuario, mes_presentacion = excluded.mes_presentacion,
      anio_presentacion = excluded.anio_presentacion, pago_inmediato = excluded.pago_inmediato, dias_credito = excluded.dias_credito, factura_original = excluded.factura_original,
      regimen_isr_id = excluded.regimen_isr_id, clasificacion_id = excluded.clasificacion_id, galones_super = excluded.galones_super, galones_regular = excluded.galones_regular,
      galones_diesel = excluded.galones_diesel, exento = excluded.exento, retencion = excluded.retencion, retencion_valor = excluded.retencion_valor,
      retencion_formulario = excluded.retencion_formulario, retencion_fecha = excluded.retencion_fecha, orden_compra = excluded.orden_compra, modulo_factura = excluded.modulo_factura,
      numero_cheque = excluded.numero_cheque, usuario_modifica_anterior = excluded.usuario_modifica_anterior, fecha_modifica_anterior = excluded.fecha_modifica_anterior,
      tipo_compra_anterior = excluded.tipo_compra_anterior, poliza_anio = excluded.poliza_anio, poliza_mes = excluded.poliza_mes, poliza_numero = excluded.poliza_numero,
      pct_iva = excluded.pct_iva, pct_retencion = excluded.pct_retencion, propina = excluded.propina, fecha_transferencia = excluded.fecha_transferencia,
      clasificacion_pago = excluded.clasificacion_pago, usuario_autoriza = excluded.usuario_autoriza, tipo_periodo_compra = excluded.tipo_periodo_compra,
      transaccion_retencion = excluded.transaccion_retencion, valor_cambio_anterior = excluded.valor_cambio_anterior, documento_anterior = excluded.documento_anterior,
      proveedor_anterior = excluded.proveedor_anterior, transaccion_anterior = excluded.transaccion_anterior, regimen_isr_anterior = excluded.regimen_isr_anterior,
      fecha_ingreso_anterior = excluded.fecha_ingreso_anterior, usuario_anula_anterior = excluded.usuario_anula_anterior, fecha_anula_anterior = excluded.fecha_anula_anterior,
      cuenta_bancaria_anterior = excluded.cuenta_bancaria_anterior, transferencia_anterior = excluded.transferencia_anterior, banco_anterior = excluded.banco_anterior,
      contrasena_anterior = excluded.contrasena_anterior, exento_anterior = excluded.exento_anterior, anio_presentacion_anterior = excluded.anio_presentacion_anterior,
      retencion_valor_anterior = excluded.retencion_valor_anterior, fecha_documento_anterior = excluded.fecha_documento_anterior,
      fecha_vencimiento_anterior = excluded.fecha_vencimiento_anterior
    returning (xmax = 0) as nueva, documento like '% (MIGRADA)' as migrada, exento_anterior is not null and galones_super + galones_regular + galones_diesel > 0 as con_idp)
  select count(*) filter (where nueva), count(*) filter (where not nueva), count(*) filter (where migrada), count(*) filter (where con_idp) into v_n, v_a, v_doc, v_idp from x;
  alter table public.compras enable trigger compras_preparar;
  perform set_config('fin.migracion', '', true);

  raise notice '%', format('Compras de la organización 2 (parte 25 de 116): %s nuevas, %s actualizadas.%s%s%s%s%s',
    v_n, v_a,
    case when v_ren > 0 then format(' %s compras registradas en el sistema pasaron a números después de las migradas.', v_ren) else '' end,
    case when v_prov > 0 then format(' %s proveedores creados (no venían en ACT_PROVEEDORES).', v_prov) else '' end,
    case when v_reg > 0 then format(' %s regímenes ISR creados.', v_reg) else '' end,
    case when v_idp > 0 then format(' %s compras de combustible con el IDP descontado del exento.', v_idp) else '' end,
    case when v_doc > 0 then format(' %s documentos ya registrados en el sistema llevan « (MIGRADA)».', v_doc) else '' end,
    '');
end;
$compras$;
